 ['id'=>1,'name'=>"Tau'ri",'bonus_label'=>'Balanced industry and diplomacy','attack_modifier'=>1.000,'defense_modifier'=>1.000,'income_modifier'=>1.080,'covert_modifier'=>1.040],
 ['id'=>2,'name'=>'Goa\'uld','bonus_label'=>'Command authority and military pressure','attack_modifier'=>1.120,'defense_modifier'=>1.040,'income_modifier'=>1.000,'covert_modifier'=>1.000],
 ['id'=>3,'name'=>'Asgard','bonus_label'=>'Advanced research and defensive systems','attack_modifier'=>1.000,'defense_modifier'=>1.140,'income_modifier'=>1.000,'covert_modifier'=>1.120],
 ['id'=>4,'name'=>'Wraith','bonus_label'=>'Aggressive fleets and population conversion','attack_modifier'=>1.080,'defense_modifier'=>1.000,'income_modifier'=>1.060,'covert_modifier'=>1.000],
 ['id'=>5,'name'=>'Tok\'ra','bonus_label'=>'Covert intelligence and resistance networks','attack_modifier'=>1.000,'defense_modifier'=>1.000,'income_modifier'=>1.040,'covert_modifier'=>1.140],
];
