foreach($governmentNames as $i=>$name)$fallbackGovernments[]=['id'=>$i+1,'name'=>$name,'description'=>'A distinct political system with economy, military, research, colony, fleet, diplomacy, and Dark Matter modifiers.','economy_modifier'=>1.000,'research_modifier'=>1.000,'military_modifier'=>1.000,'defense_modifier'=>1.000,'covert_modifier'=>1.000,'diplomacy_modifier'=>1.000,'colony_modifier'=>1.000,'fleet_modifier'=>1.000,'population_modifier'=>1.000,'dark_matter_modifier'=>1.000];
