if($pdo){try{$options=(new FactionService($pdo))->options();if($options['races'])$races=$options['races'];if($options['governments'])$governments=$options['governments'];}catch(Throwable $e){$error='Faction data is unavailable until the database migrations are imported.';}}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$old['display_name']=trim((string)($_POST['display_name']??''));$old['username']=trim((string)($_POST['username']??''));$old['race_id']=(int)($_POST['race_id']??0);$old['government_id']=(int)($_POST['government_id']??0);$password=(string)($_POST['password']??'');
 if(!$pdo)$error='Database unavailable. Start MySQL/MariaDB and import migrations 000 through 013 before creating an account.';
 elseif(!preg_match('/^[A-Za-z0-9_]{3,50}$/',$old['username'])||mb_strlen($old['display_name'])<2||mb_strlen($old['display_name'])>100||strlen($password)<8||$old['race_id']<1||$old['government_id']<1)$error='Choose a valid commander name, username, race, government, and password of at least 8 characters.';
 else try{$stmt=$pdo->prepare('SELECT id FROM races WHERE id=?');$stmt->execute([$old['race_id']]);if(!$stmt->fetchColumn())throw new RuntimeException('Selected race is unavailable.');$stmt=$pdo->prepare('SELECT id FROM government_types WHERE id=? AND is_active=1');$stmt->execute([$old['government_id']]);if(!$stmt->fetchColumn())throw new RuntimeException('Selected government is unavailable.');$stmt=$pdo->prepare('INSERT INTO players(username,display_name,password_hash,race_id) VALUES(?,?,?,?)');$stmt->execute([$old['username'],$old['display_name'],password_hash($password,PASSWORD_DEFAULT),$old['race_id']]);$playerId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO player_resources(player_id) VALUES(?)')->execute([$playerId]);(new FactionService($pdo))->selectRegistration($playerId,$old['race_id'],$old['government_id']);$stmt=$pdo->prepare('SELECT p.*,r.name AS race FROM players p JOIN races r ON r.id=p.race_id WHERE p.id=?');$stmt->execute([$playerId]);login_user($stmt->fetch(PDO::FETCH_ASSOC));header('Location: index.php');exit;}catch(Throwable $e){$error=str_contains(strtolower($e->getMessage()),'duplicate')?'That username or email is already in use.':$e->getMessage();}
