function pct($n):string{return sprintf('%+.1f%%',((float)$n-1)*100);}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create account · Universe Civilization: Empire at Wars</title><link rel="stylesheet" href="assets/app.css"><style>.register-shell{width:min(1180px,100%);margin:0 auto}.register-card{background:#fff;border:1px solid #ddd;padding:28px}.register-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.choice-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.choice{display:block;border:1px solid #ddd;padding:14px;cursor:pointer;background:#fff}.choice:hover,.choice.selected{border-color:#111;background:#fafafa}.choice input{position:absolute;opacity:0}.choice strong{display:block}.choice small{display:block;color:#777;line-height:1.45;margin-top:5px}.bonus-line{display:flex;gap:8px;flex-wrap:wrap;margin-top:9px}.bonus{font-size:10px;border:1px solid #aaa;padding:4px 6px}.selection-summary{border:1px solid #111;background:#fafafa;padding:15px;min-height:120px}.resource-preview{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:12px}.resource-preview div{border:1px solid #ddd;padding:9px}.resource-preview small{display:block;color:#777;font-size:10px}.resource-preview strong{display:block;margin-top:4px}.register-actions{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-top:20px}@media(max-width:800px){.register-grid,.choice-grid{grid-template-columns:1fr}.resource-preview{grid-template-columns:repeat(2,1fr)}.register-actions{display:grid}.register-actions .button{width:100%}}</style></head><body class="auth-page"><main class="register-shell"><div class="register-card"><div class="brand auth-brand"><div class="brand-mark">S</div><div><strong>UNIVERSE CIVILIZATION: EMPIRE AT WARS</strong><small>COMMAND INTERFACE</small></div></div><p class="kicker">NEW COMMANDER / REGISTRATION</p><h1>Create your realm</h1><p class="auth-copy">Choose a race and government. Their combined modifiers become the starting identity of your realm and are enforced by the server.</p><?php if($error):?><div class="error-box"><?=e($error)?></div><?php endif;?><form method="post" id="registration-form"><?=csrf_field()?><div class="register-grid"><section><h2>1. Commander identity</h2><label>Commander name<input name="display_name" value="<?=e($old['display_name'])?>" required minlength="2" maxlength="100"></label><label>Username<input name="username" value="<?=e($old['username'])?>" required pattern="[A-Za-z0-9_]{3,50}" autocomplete="username"></label><label>Password<input type="password" name="password" minlength="8" required autocomplete="new-password"></label><div class="resource-preview"><div><small>Metal</small><strong>820,000</strong></div><div><small>Crystal</small><strong>460,000</strong></div><div><small>Naquadah</small><strong>1,240,000</strong></div><div><small>Dark Matter</small><strong>2,500</strong></div><div><small>Food</small><strong>10,000</strong></div><div><small>Water</small><strong>10,000</strong></div><div><small>Population</small><strong>100</strong></div><div><small>Capacity</small><strong>1,000</strong></div></div></section><section><h2>2. Select race</h2><div class="choice-grid"><?php foreach($races as $race):?><label class="choice race-choice"><input type="radio" name="race_id" value="<?=((int)$race['id'])?>" data-name="<?=e($race['name'])?>" <?=((int)$old['race_id']===(int)$race['id']?'checked':'')?>><strong><?=e($race['name'])?></strong><small><?=e($race['bonus_label']??'Strategic specialization')?></small><div class="bonus-line"><span class="bonus">ATK <?=e(pct($race['attack_modifier']??1))?></span><span class="bonus">DEF <?=e(pct($race['defense_modifier']??1))?></span><span class="bonus">INC <?=e(pct($race['income_modifier']??1))?></span><span class="bonus">COV <?=e(pct($race['covert_modifier']??1))?></span></div></label><?php endforeach;?></div></section></div><section><h2>3. Select government</h2><div class="choice-grid"><?php foreach($governments as $gov):?><label class="choice government-choice"><input type="radio" name="government_id" value="<?=((int)$gov['id'])?>" data-name="<?=e($gov['name'])?>" <?=((int)$old['government_id']===(int)$gov['id']?'checked':'')?>><strong><?=e($gov['name'])?></strong><small><?=e($gov['description']??'Political and economic doctrine')?></small><div class="bonus-line"><span class="bonus">ECO <?=e(pct($gov['economy_modifier']??1))?></span><span class="bonus">RES <?=e(pct($gov['research_modifier']??1))?></span><span class="bonus">MIL <?=e(pct($gov['military_modifier']??1))?></span><span class="bonus">DIP <?=e(pct($gov['diplomacy_modifier']??1))?></span></div></label><?php endforeach;?></div></section><div class="selection-summary" id="summary"><strong>Selection summary</strong><p>Choose one race and one government to preview the combined realm identity.</p></div><div class="register-actions"><a class="button outline" href="login.php">Already registered? Log in</a><button class="button dark" type="submit">Create account and enter the Command Center <span>→</span></button></div></form></div></main><script>const choices=[...document.querySelectorAll('.choice')];function refresh(){choices.forEach(c=>c.classList.toggle('selected',c.querySelector('input').checked));const r=document.querySelector('input[name="race_id"]:checked')?.dataset.name||'No race';const g=document.querySelector('input[name="government_id"]:checked')?.dataset.name||'No government';document.querySelector('#summary').innerHTML='<strong>Selection summary</strong><p><b>'+r+'</b> race + <b>'+g+'</b> government. The PHP server will validate both choices, write the registration, initialize resources, and apply modifiers in a transaction.</p>'}choices.forEach(c=>c.addEventListener('change',refresh));refresh();</script></body></html>
